<?php
require_once __DIR__.'/../includes/init.php';require_login();$page_title='Staff Attendance';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$q=$pdo->prepare('INSERT INTO staff_attendance(staff_id,attendance_date,status) VALUES(?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status)');foreach(($_POST['status']??[]) as $id=>$st)if(in_array($st,['present','absent','late','leave'],true))$q->execute([(int)$id,$_POST['date'], $st]);flash('Staff attendance saved.');go('attendance/staff.php');}
$staff=$pdo->query("SELECT id,employee_no,full_name FROM staff WHERE status='active' ORDER BY full_name")->fetchAll();$date=$_GET['date']??date('Y-m-d');$q=$pdo->prepare('SELECT staff_id,status FROM staff_attendance WHERE attendance_date=?');$q->execute([$date]);$old=[];foreach($q as $r)$old[$r['staff_id']]=$r['status'];
require __DIR__.'/../includes/header.php';?><h1>Staff Attendance</h1><div class="panel"><form method="get"><label>Date</label><input type="date" name="date" value="<?=h($date)?>"><button>Load</button></form></div><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="date" value="<?=h($date)?>"><div class="panel"><table><tr><th>Employee #</th><th>Name</th><th>Status</th></tr><?php foreach($staff as $s):?><tr><td><?=h($s['employee_no'])?></td><td><?=h($s['full_name'])?></td><td><select name="status[<?=$s['id']?>]"><?php foreach(['present','absent','late','leave'] as $v):?><option <?=$v===($old[$s['id']]??'present')?'selected':''?>><?=$v?></option><?php endforeach;?></select></td></tr><?php endforeach;?></table><button>Save attendance</button></div></form><?php require __DIR__.'/../includes/footer.php';?>